    faq_a_bag_examples_list: "Нова сумка приходить із прикладами, які можна змінити або видалити, як і все інше: Дім (покупки, рецепти, меню на тиждень), Родина (маленькі радощі, список до дня народження, гуртки й заняття), Ідеї (ідеї на вихідні, ідеї подарунків залежно від того, наскільки близька людина, і що зробити із заощадженими грошима) і Подорожі (місця, де хочеться побувати, що взяти в подорож, речі в готель і список для перельоту за кордон). Сумка, яка вже була, один раз отримує найновіші – у свої власні кишені.",
