    faq_a_shop_holidays: "У списку покупок торкніться подарунка: по черзі з’являться свята вашої країни (вибраної в Налаштуваннях) з датами – вони щороку обчислюються самі. Торкніться свята, щоб відкрити готовий список того, що до нього зазвичай купують; усе вже вибрано (крім того, що вже є у вашому списку), зніміть позначку з непотрібного й торкніться «Додати до списку». За два тижні до свята вгорі списку з’являється маленька картка; ✕ ховає її до наступного свята.",
