    shop_hol_btn: "Що купити до свята",
    shop_hol_items_title: "{holiday} – що купити?",
    shop_hol_not_now: "Не зараз",
    faq_a_shop_delivery: "У списку покупок торкніться вантажівки: виберіть, що в доставці (вибрано все), коли її привезуть – сьогодні, завтра чи іншого дня – і в який час (ранок, день, вечір або «Інше…», щоб вказати свої години). Ці товари переходять у картку «У дорозі» вгорі списку, із зазначенням дня й годин. Коли настає цей день, у «Моєму дні» з’являється «Доставку привезли?» (а на картці – «Привезли?»). Якщо привезли все, товари переходять у «Купити знову». Якщо чогось бракує, торкніться того, чого не привезли, і це одразу повернеться до списку.",
    faq_a_shop_departments: "Список сам сортується за відділами супермаркету – овочі та фрукти, хліб, молочні продукти та яйця, м’ясо та риба, бакалія, заморожене, напої, снеки, побутова хімія, гігієна, для малюків і зоотовари, – щоб ви проходили ряди по черзі. Відділ визначається за назвою товару. Якщо товар потрапив не туди, торкніться його й виберіть відділ або «Інше…», щоб написати свій.",
    faq_a_shop_share_qty: "Так. Біля кожного товару + додає ще один (×2, ×3…), а − прибирає один. Кнопка «Поділитися» вгорі списку покупок надсилає весь список, акуратно розкладений за відділами, у WhatsApp, електронною поштою або як копію.",
    faq_a_shop_two_buttons: "Обидві кнопки означають «куплено». ✕ – для того, що купується один раз: товар зникає зі списку (і чекає в архіві 🗑️ на випадок помилки). ↺ – для того, що купується знову і знову: товар зникає зі списку й чекає в «Купити знову» – його відкриває маленька кнопка ↺ поруч із кошиком для сміття внизу списку, і один дотик там повертає товар до списку. У «Редагувати» всередині можна прибрати з нього товар. Коли ви додаєте товар, те, що ви вже купували, з’являється в підказках, а якщо він уже є в списку, він просто стає ×2 замість другого рядка.",
