    nm_demo_saved_2: "Йогурт із гранолою та фруктами",
    nm_demo_title: "Як працює заміна",
    faq_a_new_me_challenge_journal: "Коли челендж завершується – великий, міні-челендж чи челендж тижня, – у привітанні є кнопка 📝 Як минуло? Вона відкриває сторінку в щоденнику челенджів: як це було (п’ять облич), що допомогло, що було важко і що взяти із собою далі – нічого з цього не обов’язково, і все можна відкласти на потім. Щоденник – це діамант у чарівному рюкзаку: кожен завершений челендж із датою і тим, що було написано, найновіші вгорі – торкніться будь-якого, щоб прочитати, змінити його або поділитися ним (надсилається тільки те, що є на сторінці). Завершений челендж також отримує медаль у досягненнях, у розділі «Виконані челенджі». Щоденник челенджів окремий від звичайного щоденника.",
    faq_q_new_me_challenge_journal: "Що таке щоденник челенджів?",
