    nm_chj_mood_4: "Добре",
    nm_chj_mood_5: "Чудово",
    nm_chj_q: "Як минув челендж?",
    nm_chj_reflect_btn: "Як минуло?",
    nm_chj_save: "Зберегти в щоденнику челенджів",
    nm_chj_saved: "Збережено в щоденнику челенджів",
    nm_chj_share_text: "Челендж у New Me виконано ✨",
