    nm_chj_write: "Написати, як минуло",
    nm_swap_time: "Час",
    faq_a_ai_reminder_in_text: "Так – напишіть його разом із завданням, наприклад «завтра о 17:00 забрати посилку, з нагадуванням за годину». Нагадування зберігається в самому завданні: за годину, за пів години, за день і так далі, а «нагадай мені» без часу означає за 10 хвилин. Нагадування, написане в тексті, має пріоритет над полем нагадування в тому самому вікні.",
    faq_q_ai_reminder_in_text: "Чи можна попросити ШІ-асистента про нагадування в тому самому запиті?",
    myday_meals_all_done: "Усі прийоми їжі на сьогодні позначено 🍽️",
    nm_tour_week_text: "Маленький челендж на тиждень. ✓ щодня – а наприкінці ключ.",
    books_home_chip: "{title} · стор. {page}",
    books_home_of: "із {total}",
    books_home_off_toast: "Книжка зникла з головного екрана",
    books_home_on_toast: "Книжка на головному екрані 📖",
    books_home_pin: "На головному екрані",
    books_home_q: "На якій я сторінці?",
    books_home_save: "Зберегти",
    faq_a_books_home_chip: "Так. У «Куточку читання», на картці книжки, яку читаєте, торкніться 📌 На головному екрані. Під привітанням на головному екрані з’явиться маленька кнопка з книжкою та сторінкою – торкніться її, введіть новий номер сторінки й збережіть, і прогрес запишеться (також у «Куточку читання»). Повторний дотик до 📌 прибирає її. Там може бути кілька книжок одночасно – по кнопці для кожної – і так само на кожному пристрої.",
    faq_a_new_me_week_challenge: "Маленький челендж на один тиждень, який ви обираєте самі. У коридорі є велика картка: «Над чим працюватимете цього тижня?» – торкніться її, оберіть напрям (з собою, з іншими, вчитися й рости, спокій, маленькі сміливі кроки, дім і розпорядок) і челендж та виберіть, коли він починається. Ті самі челенджі є й на екрані челенджів, у розділі 🌱 Особистий розвиток. Щодня ставте ✓ на картці (один вільний день на тиждень), а кожен завершений тиждень приносить новий ключ до таємного світу. «Читати 2 сторінки на день» відмічається сам за сторінками, записаними в «Куточку читання». Коли тиждень закінчується, 📌 Залишити як щоденне завдання додає його до «Мого розпорядку» на обраний вами час, із ✓ щодня. Одночасно діє один челендж тижня; великі й міні-челенджі тривають поруч із ним.",
    faq_a_room_genie: "На веранді біля моря дотик до лампи Аладдіна випускає духа лісу – і починається розмова: яке ваше бажання (що хотілося б змінити в житті), яким буде відчуття, коли воно здійсниться, що важко на шляху і як можна обернути теперішню ситуацію на добро. Потім – скільки це приблизно триватиме, перший маленький крок і ще два, а також «якщо… то…» на випадок, коли стане важко. Наприкінці все бажання постає крок за кроком, і його можна зробити ціллю в «Моїх цілях» (кроки стають етапами на шляху, з датою за обраним часом; там усе можна змінити) або зберегти у щоденнику – і тоді дух прощається. Нічого не зберігається, якщо не обрати одне з двох. З другого візиту дух спершу запитує, чи хотілося б змінити в житті ще щось: так – та сама розмова; не зараз – нагадування досягати вже поставлених цілей. Дух виходить раз на день: після того як бажання збережено (або після «Не зараз»), він відпочиває до завтра. Запитання ґрунтуються на відомому способі перетворювати бажання на план: бажання, результат, перешкода й план.",
    faq_q_books_home_chip: "Чи можна бачити свою книжку й сторінку на головному екрані?",
    faq_q_new_me_week_challenge: "Що таке челендж тижня?",
