    room_drawer_aria: "Маленька шафка",
    nm_me_choose: "Обрати",
    nm_me_on_screen: "На екрані",
    faq_a_new_me_game: "У New Me ігрові кнопки завжди на тому самому місці – у коридорі, у таємній кімнаті й будь-де в лісі; змінюється лише картина посередині. Угорі: день шляху, ключі, серія та сьогоднішня енергія (скільки з’їдено з плану), а під ними – наступна місія: наступний прийом їжі в його час (дотик відкриває його, із ✓ З’їдено). Збоку: увесь день, челенджі й мій шлях, а поруч із ними – челендж тижня: його 7 днів і ✓ на сьогодні. Унизу: чарівний рюкзак (усе в New Me – мапа світу, мій шлях, покупки, досягнення, щоденник челенджів, заміри, фото, календар місяця, щоденна таблиця, нагадування, меню в PDF і налаштування; відкривається як окремий екран). Мапа світу, яка лежить у рюкзаку першою, показує всі місця лісу – торкніться місця, щоб перейти туди; на замкненому місці видно, скільки ключів потрібно. Sky – ваш персонаж на стежці в лісі: він починає як Sky 1, після кількох челенджів (4 ключі) виростає в Sky 2, а ближче до кінця (9 ключів) – у Sky 3, і перевтілення відбувається просто на очах. Торкніться Sky, щоб побачити всі етапи – будь-який уже досягнутий етап можна обрати знову, тож попередній може повернутися. Sky ширяє: його перетягують пальцем або мишею, і вхід, якого він торкнеться, відкривається (на замкненому написано, скількох ключів бракує). Sky також іде з вами в кожну кімнату й кожне місце та ширяє там, де ви його залишите: перетягніть його будь-куди, а світне кільце під ним потягніть, щоб повністю повернути його навколо своєї осі; він дивиться в той бік, куди рухається (на комп’ютері: стрілки рухають його, Q і E повертають). У коридорі маленький значок 🏠 під верхньою панеллю повертає на головний екран; у кожній кімнаті й місці кнопка в тому самому куті повертає в коридор.",
    faq_q_new_me_game: "Як працюють ігрові кнопки, мапа світу і Sky?",
