    room_magic_song_rec3: "Дзвіночки водоспаду",
    faq_a_new_me_menu_build: "Спершу анкета запитує, які у вас прийоми їжі та коли (2 прийоми їжі + перекус, 2 прийоми їжі + легка вечеря або і те, і те), і чи є щось увечері – поїсти чи випити, що саме й о котрій. У варіанті «2 прийоми їжі + перекус» це обід (11:30) і вечеря (19:00), а перекус – о 16:00. Потім з'являються всі варіанти для цих прийомів їжі. Оберіть до 2 улюблених для кожного прийому – у меню буде «це або те». У деяких варіантах (піта з пастою, кукурудзяні пластівці з молоком, щось легке) можна обрати до 3 речей, що подобаються, кожну у своїй порції, і в меню буде «це або те, або те»; калорії залежать від вибраного. Кава й напої працюють так само. Кожен вибір збалансований, тож день складається рівно в 1300 або 1500. Щоб змінити будь-коли: ⚙️ Налаштування → 🍽️ Складіть своє меню або «Оберіть до 3, що подобаються» на картці прийому їжі.",
