    faq_a_myday_water_toggle: "Так. Склянка води в «Моєму дні» (з + для ще однієї склянки) типово показується. Щоб приховати її, вимкніть «Показувати воду в „Моєму дні“» у Налаштуваннях > Персоналізація і календар. Нічого не видаляється – «Моніторинг Води» працює далі, а після повторного ввімкнення склянка повертається.",
    faq_q_myday_water_toggle: "Чи можна приховати воду в «Моєму дні»?",
    myday_water_toggle_label: "Показувати воду в «Моєму дні»",
    faq_a_routine_newme_sync: "З New Me в ⚙️ «Мого розпорядку» є перемикач «Синхронізація з New Me». Коли він увімкнений (типово), сьогоднішні прийоми їжі New Me видно в «Моєму дні» і в «Моєму розпорядку» – замість прихованих прийомів їжі розпорядку. Коли вимкнений, прийоми їжі New Me зникають з обох, а розпорядок стає точно таким, яким був. Нічого не видаляється – повторне ввімкнення все повертає і питає, які прийоми їжі в розпорядку приховати.",
    faq_q_routine_newme_sync: "Як увімкнути чи вимкнути синхронізацію New Me з «Моїм розпорядком» і «Моїм днем»?",
