    faq_a_food_list_languages: "Вбудований список продуктів створювався з ізраїльськими стравами та їхніми назвами на івриті. Усіма іншими мовами кожен продукт показано під англійською назвою, а пошук знаходить будь-яку відому йому англійську назву (наприклад, 'broth' знаходить Clear soup); продукти, які мають лише назву на івриті, у списку не показуються. Усе, чого немає в списку, можна просто написати своїми словами – оцінка за допомогою ШІ працює будь-якою мовою.",
    faq_q_food_list_languages: "Чому в списку продуктів моєю мовою англійські назви та менше продуктів?",
    settings_copyright_line: "© 2026 усі права захищено. розробка застосунку: eden zabari.",
    workout_ready_replace_btn: "Замінити",
    faq_a_sport_workout_ai: "У «Мої тренування» → ⋯ → «План з ШІ» (а коли таблиця порожня — ще й на плитці поруч із готовими планами). Дайте відповідь кількома дотиками: скільки разів на тиждень, коли, місце, рівень і мета — майже всюди є й «Інше», — і за бажання додайте вільний рядок, наприклад про чутливе коліно чи пробіжку 5 км до літа. ШІ складе цілий тиждень: види тренувань, дні, час, тривалість, інтенсивність, вправи й дні відпочинку. Перед збереженням з'являється попередній перегляд: «У мою таблицю» (замість таблиці або на додачу), «Інший варіант» (до 3 разів) або «Змінити відповіді». План навмисно помірний, а якщо згадати біль чи травму, будуть м'які варіанти й порада порадитися з фахівцем. Він використовує ту саму квоту ШІ, що й розклад і розпорядок: 5 разів безкоштовно і 60 на місяць із Преміум.",
