    workout_ai_when_ph: "наприклад, після роботи або о 17:30",
    workout_ai_working: "Складаємо план…",
    faq_a_sport_workout_jar: "Кожен вид тренування має свою кольорову зірочку: біг – рожеву, ходьба – зелену, плавання – синю і так далі. Кожне тренування, записане цього тижня, з таблиці чи окремо, кидає свою зірочку в банку вгорі «Моїх тренувань», і банка наповнюється до тижневої мети (торкніться її, щоб змінити мету). Коли мету досягнуто, банка світиться. Маленька банка поруч рахує, скільки тижнів поспіль вона була повною.",
    faq_q_sport_workout_jar: "Що за кольорові зірочки й банка в «Моїх тренуваннях»?",
    faq_a_sport_workout_gcal: "Так – у ⋯ → Google Календар (коли Google Календар підключено в налаштуваннях). Кожне тренування з часом стає подією, що повторюється щотижня в його дні, а зміни в застосунку її оновлюють. Нагадування надходять лише із застосунку, тож Google не додає своїх, а тренування ніколи не з'являються в застосунку двічі. Повторний дотик видаляє з Google Календаря лише тренування.",
    faq_q_sport_workout_gcal: "Чи можуть тренування з'являтися в Google Календарі?",
    workout_gcal_btn: "Google Календар",
    workout_gcal_error: "Не вдалося оновити Google Календар – спробуємо знову під час наступної зміни",
    workout_gcal_not_connected: "Спершу підключіть Google Календар у налаштуваннях",
    workout_gcal_off_toast: "Тренування видалено з Google Календаря",
    workout_gcal_on_toast: "Ваші тренування в Google Календарі",
    faq_a_sport_workout_reminder: "Так – у тренуванні, Нагадування: за 10 хвилин, за 30 хвилин або за годину, або свій час (у тренування має бути час). Воно дзвонить, як інші нагадування, один раз і в одному місці: у застосунку, якщо він відкритий, інакше на телефоні. «Готово» записує тренування в історію, а «Ще ні» нагадає знову через 5 хвилин.",
    faq_q_sport_workout_reminder: "Чи можна отримати нагадування перед тренуванням?",
    workout_reminder_30min: "За 30 хвилин",
    workout_reminder_label: "Нагадування",
    workout_reminder_need_time: "Вкажіть час, щоб отримати нагадування",
    faq_a_sport_workout_share: "У ⋯ → «Поділитися» тиждень перетворюється на «скляне» зображення в кольорах вашої теми з ненав'язливим посиланням на застосунок (на телефоні воно одразу йде в меню «Поділитися», на комп'ютері зображення зберігається). ⋯ → «PDF для друку» відкриває охайну сторінку всього тижня з квадратиком для позначки біля кожного тренування й вправи – оберіть «Зберегти як PDF» або роздрукуйте. План також є у звіті з даними в налаштуваннях, у розділі спорту.",
    faq_q_sport_workout_share: "Як поділитися тижнем тренувань або роздрукувати його?",
    share_image_saved: "Зображення збережено – його можна додати",
    share_save_image: "Зберегти зображення",
    workout_pdf_btn: "PDF для друку",
    workout_share_btn: "Поділитися",
    faq_a_sport_workout_board: "У ⋯ → «Дошка тижня» кожен день — це колонка: перетягніть тренування на інший день (на телефоні спершу натисніть і потримайте). У тренуванні «Також у „Моєму розпорядку“» додає його в розпорядок у його час і дні, а зміни синхронізуються в обидва боки; з пункту розпорядку «Додати до моїх тренувань» робить навпаки. ✓ в будь-якому місці зараховується в обох, а в «Моєму дні» тренування видно один раз — у значку поруч із водою.",
    faq_q_sport_workout_board: "Як перенести тренування на інший день і пов'язати його з розпорядком?",
    routine_in_workouts_btn: "Відкрити в моїх тренуваннях",
