    workout_view_board: "Дошка тижня",
    workout_view_timeline: "Стрічка",
    faq_a_sport_workout_plan: "У «Відстеженні Тренувань», у «Мої тренування»: + Тренування – тип, дні, час, тривалість, інтенсивність і місце (також «Інше»). До силових, функціональних тренувань і плавання можна додати список вправ, а «Відпочинок» позначає день відпочинку. Можна почати й з готового плану. Тренування на сьогодні показано великим, під ним увесь тиждень; ✓ записує його в історію тренувань разом з інтенсивністю. У ⋯ задається мета на тиждень (тренування або хвилини) – кожне тренування кидає свою зірочку в банку.",
    faq_a_sport_workout_today: "У «Моєму дні», поруч із водою, маленький значок показує тренування на сьогодні – дотик відкриває подробиці, ✓ і ▶. ▶ запускає таймер, який іде і в значку на головному екрані, а «Завершити» записує тренування з реальним часом. Якщо в New Me триває челендж «Два тижні руху», записане тренування зараховується в ньому саме.",
