    faq_a_new_me_magic_themes: "П'ять блискучих тем, які входять до New Me: «Чарівний ліс», «Зоряний пил», «Фея троянд», «Чарівне сяйво» і «Золотий захід». Виберіть одну всередині New Me (⚙️ Налаштування > Кольори) або в Налаштуваннях > Зовнішній вигляд і екран, і пензель із блискітками розфарбує нею екран. Чарівна тема додає блискітки по всьому застосунку і за кожного дотику. Повернутися до будь-якої іншої теми можна будь-коли.",
