    apptour_focus_text: "Усе відходить убік, крім однієї справи на зараз – із великою ✓. Потім з'являється наступна.",
    apptour_m_presets_text: "Ваші збережені страви в одному місці: пошук, нещодавні, за часом дня – а ＋ додає страву на сьогодні.",
    apptour_night_text: "🌙 робить увесь застосунок темним, ☀️ повертає день.",
    apptour_noteline_text: "Напишіть і торкніться ➤ – це збережеться в нотатках. 📝 на початку перемикає на 🛒 покупки або 🍎 збережену страву.",
    apptour_search_text: "Нотатки, покупки, календар, рецепти, зошити, цілі, таблиці й книги – один пошук знаходить усе.",
    faq_a_new_me_ai_menu: "Перед меню анкета запитує, які у вас прийоми їжі та коли (2 прийоми їжі + перекус, 2 прийоми їжі + легка вечеря або і те, і те), чи буває щось невелике ввечері й о котрій, чого ви не їсте і як п'єте каву чи чай. Потім ШІ складає 3 варіанти для кожного прийому їжі – кожен за розміром його частки дня, тож день і далі складається рівно в 1300 або 1500 – та ідеї напоїв, які зберігаються як ваші постійні напої. Оберіть до 2 улюблених на кожен прийом їжі; варіанти початкового меню – одразу під ними, а в 🔄 Заміні вони йдуть після особистого меню. 🔄 Інші варіанти складає новий набір (3 рази на анкету). Щоб змінити відповіді або скласти нове меню будь-коли: ⚙️ Налаштування → ✨ Особисте меню (ШІ).",
