    settings_sub_status_newme: "Преміум входить у ваш New Me.",
    room_back_to_shelf: "До полиці",
    faq_a_new_me_day_total: "Кожен день складається рівно в план: прийоми їжі, близько 150 ккал на каву й напої протягом дня і те, що обрано на вечір, – щось невелике поїсти або щось випити. На вечір оберіть до 3, що подобаються (наприклад, банан, йогурт або 2 шматочки чорного шоколаду; або трав'яний чай, чай із краплею молока чи тепле молоко), і їхні калорії беруться з прийомів їжі. Кожен вибір урівноважується сам: менший чи більший варіант, прибраний прийом їжі, легкий сніданок і невеликий прийом їжі, що йде з ним, або вечір – різниця додається до прийомів їжі або віднімається від них, до кожного за його розміром, і під кожним написано, скільки (+ чи −) і що додати або прибрати. Уже позначений прийом їжі лишається таким, як його записано. В анкеті біля кожного прийому їжі видно його поправку, а маленька рамка показує прийоми їжі, напої, вечір і підсумок. Хочеться чогось іншого того дня? Тримайте загальну суму в тих самих калоріях або менше.",
