    books_quotes_chip: "Цитати",
    faq_a_book_quotes: "На полиці в таємній кімнаті (Цитати) або через маленьку позначку 💬 Цитати в Куточку читання – це той самий список. Натисніть «+ Цитата», напишіть рядок і виберіть книжку з Куточка читання або введіть іншу назву через «✏️ Інше»; автор необов'язковий. ✏️ змінює цитату, 🗑️ видаляє її. Цитати — це закладки, які гортаються свайпом: 🎨 угорі перемикає на фото або стіну карток.",
    faq_a_room_wish_jar: "На полиці в таємній кімнаті стоїть скляна банка для мрій. Натисніть на маленьку банку на верхній полиці (або Полиця > Банка бажань) і напишіть, яким ви хочете бачити своє життя – сміливо, без «правильно» й «неправильно». Кожне бажання складається в записку й падає в банку. «Витягнути записку» відкриває випадкову, а кожну записку можна відкрити й окремо. З другого разу, коли ви відкриваєте те саме бажання, його можна зробити ціллю й поділити на маленькі кроки. Раз на тиждень лагідно з'являється записка з одним із ваших бажань – без тиску, лише нагадування, куди ви прямуєте.",
