    room_wish_written: "Написано {date}",
    faq_a_saved_meals_page: "Збережені страви мають власну сторінку: Харчування та Виміри > ⭐ Збережені страви (або ⭐ у меню). Пошук угорі знаходить страву за назвою чи інгредієнтом, «Нещодавні» показує, що ви додавали останнім часом, а вкладки (Сніданок, Обід, Вечеря, Супи…) — кожну пору дня. «+ На сьогодні» додає страву в сьогоднішній Щоденний Трекер Їжі, у наступну вільну клітинку. Натисніть на страву, щоб змінити чи видалити її, а ＋ угорі додає нову.",
