    presets_tab_snack: "Перекуси",
    presets_tab_soup: "Супи",
    presets_tab_sweet: "Солодощі",
    faq_a_notes_sticky_look: "Нотатки — це короткий список скляних карток: 🎨 угорі нотаток змінює вигляд усіх нотаток – списку, кнопок днів угорі й вікна, де пишуть нотатку (скло, чистий список, картки або скотч). Нотатка, яку перетягують, зберігає саме свій вигляд і колір. Натисніть на текст нотатки, щоб відкрити: там можна її змінити, поміняти кольори і побачити, коли її писали востаннє. Натисніть ○, коли справу зроблено, а × переміщує її в архів (🗑️ унизу списку повертає її). Перетягніть за ⠿, щоб змінити порядок, під «Пізніше» або на день угорі. ! позначає нотатку як термінову – вона м’яко піднімається до перших рядків із маленькою позначкою «Терміново»; ще один дотик знімає позначку.",
    faq_q_notes_sticky_look: "Як відкрити, змінити чи прибрати нотатку?",
    note_to_archive_btn: "Перемістити в архів",
    faq_a_routine_clash: "Якщо в цей час у ті самі дні вже є пункт, з'являться два варіанти: «Замінити» – новий пункт займає цей час, а для попереднього вибирається інший (під час редагування наявного пункту пропонується його попередній час, і вони просто міняються місцями), або «Обидва» – обидва лишаються в один і той самий час, один під одним. Якщо дні різні (наприклад, один з неділі по четвер, а інший у п'ятницю), нічого не питається.",
    faq_q_routine_clash: "Що буде, якщо поставити пункт розпорядку на вже зайнятий час?",
    routine_clash_both: "✌️ Обидва – обидва на {time}",
    routine_clash_move_btn: "Перенести й зберегти",
    routine_clash_move_to: "На який час перенести «{title}»?",
    routine_clash_replace: "🔄 Замінити – і перенести «{title}» на інший час",
    routine_clash_title: "На {time} вже є: {title}",
    faq_a_new_me_coffee: "Під сьогоднішнім меню є коротке зведення: скільки калорій у всіх прийомах їжі за день, скільки лишилося на каву й напої, і кнопки вибраних кави та напоїв – одне торкання додає до «Напоїв». В «Оберіть до 3, що подобаються» під кнопками (і в анкеті) можна вибрати, що показувати: вода / газована вода, трав'яний чай, дієтичний напій, чорна / американо (~5), чай із краплею молока (~25), кава на воді з молоком або рослинним молоком до 100 мл (~50), легке какао, тепле молоко або звичайна кава / лате (~120).",
    faq_q_new_me_coffee: "Де додати каву і як дізнатися, скільки лишилося на день?",
