    faq_a_recipe_examples: "Під вашими рецептами є приклади: сніданки, салати, супи, основні страви, гарніри, перекуси, десерти й веганські страви. У кожного вказано час приготування, калорії на порцію і скільки грамів важить одна порція. Торкніться рецепта, щоб відкрити його, а кнопка «Зберегти в мої рецепти» створить вашу копію, яку можна редагувати. Мітки категорій фільтрують, а повторне торкання тієї ж мітки знову показує все.",
