    faq_a_recipe_scan_multi: "Так. У «Додати Рецепт» торкніться 📷 і виберіть одне фото або кілька (до 6; PDF теж підходить). Кожне з'явиться в короткому списку, де треба вибрати, що на ньому: Усе, Інгредієнти чи Приготування, а «➕ Ще фото» додає нові. Потім торкніться «✨ Сканувати рецепт»: ШІ збере все в один рецепт по порядку й без повторів, і це рахується як одне сканування. Кілька фото, вибраних у 📷 Фото в помічнику ШІ, теж відкриваються тут.",
