    faq_a_new_me_small_breakfast: "Легкий сніданок (близько 170 ккал): піта зі спельти (до 100 ккал) з пастою або сиром, а також овоч – оберіть до 3, що подобаються, наприклад 1 чайну ложку шоколадної пасти, 1 чайну ложку арахісової пасти чи скибочку твердого сиру (до 22%). Оскільки він невеликий, з ним іде «Плюс невеликий прийом їжі» в інший час (через півтори години, наприклад 11:30 → 13:00 – можна обрати будь-який інший час): ще одна піта з пастою, протеїновий йогурт і фрукт, рисові хлібці та сир, пластівці з молоком або половинка піти та яйця – приблизно до 200 ккал, зі своєю позначкою ✓. Те, що ще лишається, ділиться між іншими прийомами їжі, і кожен показує, скільки йому додалося, тож підсумок дня лишається як у плані. Його можна обрати в анкеті або змінити на нього лише на сьогодні через 🔄 – наприклад, коли снідаєте пізно.",
