    faq_a_ai_icon: "Так – у Налаштуваннях > Зовнішній вигляд і екран. Типово це м'яка бульбашка, а з Premium можна обрати ще мозок, що пливе, або робота.",
    faq_a_new_me_favorites: "Так. В анкеті (і під час повторного проходження з налаштувань) можна обрати до 2 варіантів для кожного прийому їжі. Перший показано в меню, а під ним – рядок «або» з другим: дотик до нього змінює на нього лише на сьогодні. А якщо сніданок не з'їдено вчасно, «⏰ Пізніше» переносить його на пізніший час дня, не змінюючи калорій.",
    faq_a_theme_mode: "Деякі особливі теми найкраще виглядають у темному режимі – Акварель, Північне сяйво, Барбі й обидві теми з блискітками, – тож вибір однієї з них вмикає темний режим, а вибір будь-якої іншої теми (і ракети теж) – світлий. Чорна й Темно-сіра лишаються темними. Потім завжди можна змінити через 🌙 у меню або «Світлий Режим» у налаштуваннях.",
    faq_a_water_month: "В обліку води. Біля кожного запису в сьогоднішньому журналі вказано час, коли його додано, а «Таблиця за місяць» відкриває весь місяць: у кожному дні видно, скільки літрів випито (✓, коли денну ціль досягнуто), а дотик до дня показує його записи з часом.",
