    faq_a_room_records: "Програвач стоїть у кімнаті від самого початку, на пеньку біля крісла. Його платівки відкривають на YouTube офіційні кліпи великих хітів останніх років, а під ними – п'ять спокійних мелодій, що звучать просто в кімнаті: платівка крутиться, поки вони грають, а «⏹ Стоп» вимикає музику.",
    faq_a_room_roof_gifts: "Вони з'являються з 8-м ключем. Дотик до телескопа дає змогу зазирнути в нього: нічне небо зблизька – перетягуйте (або користуйтеся стрілками), щоб роззирнутися, – і завершені челенджі складаються в ньому в сузір'я, по зірці на кожен; дотик до зірки показує, який це був челендж. Дотик до маленької скрині відкриває її – поки що вона порожня – а ще один дотик зачиняє.",
