    faq_a_home_note_line: "Напишіть у рядку посередині головного екрана й торкніться ➤ (або Enter) — нотатка збережеться в «Нотатках». Торкніться 📝 на початку рядка, і він стане 🛒: тоді написане потрапить до списку покупок. Торкніться ще раз — 🍎: введіть кілька літер, з'являться відповідні збережені страви, і один дотик запише страву в сьогоднішні прийоми їжі. З 🎤 можна просто сказати вголос.",
    faq_a_night_mode: "Відкрийте меню ☰ і торкніться 🌙 угорі — увесь застосунок стане темним. ☀️ на тому самому місці поверне день. Це є й у Налаштуваннях, у пункті «Світлий Режим».",
    faq_q_home_note_line: "Як написати швидку нотатку з головного екрана?",
