    menu_day_mode: "Денний режим",
    menu_night_mode: "Нічний режим",
    faq_a_secret_room_yoga: "Наприкінці стежки в лісі є сяйлива брама, а за нею, біля водоспаду, лісові створіння – Лумі, Пуффі, Ніксі та Спарклет – сидять півколом на своїх килимках, а Флора, вчителька йоги, сидить навпроти них на окремому килимку на камені. Торкніться Флори: вона розплющує очі, усе наближається, і розмова починається неквапно, з часом на читання – Флора запитує, як у всіх справи, кожне створіння відповідає від свого імені (біля кожного рядка є маленький малюнок того, хто говорить), а потім вона запитує вас, як ви почуваєтеся з близькими людьми. Розмова йде за вашими відповідями: хороші люди, хтось, із ким важко, чи трохи самотності. Кожен шлях закінчується маленькою місією (її можна одразу додати в «Мій день»; якщо місія – щось написати, для цього є місце, і написане зберігається в чарівному щоденнику) і позою з трьома вдихами разом. ↩ повертає на крок назад, а ✦ починає нову розмову. Наступний ключ відкриває водоспад: якщо сісти на камінь, усе зникає і лишається тільки шум води. Якщо схилитися над ставком, із води з'являється запитання – що зробило б сьогодні ваше справжнє «я»? – і відповідь стає маленькою справою в «Моєму дні». Це теплий момент, а не заміна розмові з фахівцем.",
