    routine_time_taken: "На цей час уже щось є: {title}",
    faq_a_new_me_times: "В анкеті на початку і будь-коли в налаштуваннях New Me → «Час прийомів їжі». Якщо в розпорядку вже є час для їжі, він береться звідти – а прийоми їжі розпорядку можна сховати й показувати замість них прийоми їжі New Me. Якщо ні – оберіть, скільки прийомів їжі на день (2 прийоми їжі + перекус / 2 прийоми їжі + легка вечеря / 2 прийоми їжі + перекус + легка вечеря) і коли кожен. У варіанті «2 прийоми їжі + перекус» це обід об 11:30, перекус о 16:00 і вечеря о 19:00 (кожен можна змінити). Це ваш час їжі всюди: у коридорі, у «Моєму дні», у «Моєму розпорядку» і в нагадуваннях. Що б не вибрати, калорійність дня лишається такою ж: те, що прибрано, ділиться між іншими прийомами їжі.",
