    nm_times_saved: "Час прийомів їжі збережено",
    nm_times_title: "Час прийомів їжі",
    faq_a_routine_exact_time: "Так. Якщо описати розпорядок ШІ з точним часом (наприклад, «16:10 трейдинг»), він збережеться саме так, без округлення до цілої години. Усе, що записано в розпорядку, завжди видно на дошці, навіть якщо цю годину не вибрано в налаштуваннях годин, а перед видаленням години, у якій щось записано, з'явиться запитання. Час можна змінити й уручну: торкнися часу у вікні пункту й вибери годину та хвилини.",
