    routine_hour_remove_text: "Те, що записано на цей час, буде видалено з розпорядку: {title}",
    routine_hour_remove_title: "Прибрати {time}?",
    faq_a_routine_ai: "У «Мій розпорядок» відкрийте ⚙️ (або ➕) і торкніться «Новий розпорядок з ШІ»: опишіть розпорядок простими словами – наприклад, «підйом о 7, спорт о 8, робота до 17» – і ШІ створить нову вкладку з годинами та справами. Якщо в тексті вказано дні («у будні»), вкладка відкриватиметься в ці дні, а різні розпорядки для різних днів стануть окремими вкладками. Потім усе можна редагувати як звичайно.",
    faq_a_routine_daysoff: "У «Мій розпорядок» торкніться ➕, а потім «Вихідні дні»: виберіть дні (наприклад, суботу й неділю) і розпорядок у ці дні – без розкладу (лишається вільно), свій розпорядок або розкажіть ШІ, що ви робите, щоб він його склав. Вихідні отримують власну вкладку, і в ці дні «Мій розпорядок» і «Мій день» показують лише її.",
