    routine_daysoff_what: "А який розпорядок у ці дні?",
    routine_daysoff_which: "Які дні?",
    faq_a_secret_room_diary: "Тільки ви. Сторінки щоденника зберігаються в акаунті, тож вони є на всіх пристроях, і ніхто інший їх не бачить. Його відкриває чарівний щоденник на столі в таємній кімнаті, а також щоденник у музичному куточку. Під новою сторінкою — згорнута таблиця місяця: крапка позначає кожен день, у якому є сторінка, а дотик до дня відкриває його сторінки; там же можна видалити сторінку. Коли щоденник уже відкрито, його можна додати й до головного меню – перемикачем у самому щоденнику або в налаштуваннях New Me.",
    faq_a_secret_room_places: "Кожен вхід біля лісової брами відчиняється своїм ключем. За ними: веранда біля моря (на столику – лампа Аладдіна: дотик – і з неї в чарівному тумані здіймається дух лісу, кружляє довкола й розпочинає розмову про ваше бажання – див. «Що робить джин з лампи?»), гітара і щоденник (гітара грає коротку спокійну мелодію й затихає сама, а кожна з трьох платівок, що висять на дереві, грає свою чарівну мелодію, а повторний дотик її зупиняє; у щоденнику на пеньку пишуть), кімната дихання (тихе озеро на заході сонця; на воді пливе ліхтарик-лотос: торкніться його, напишіть бажання, і він відпливає з ним далеко вглиб озера; чарівною паличкою можна написати на піску те, що хочеться відпустити, і напис лишається, доки його не зітруть пальцем) і стежка в лісі (вона відкривається вночі, а дотик до ліхтарів перемикає на день; на великій гілці висять чарівні гойдалки, на лавці можна посидіти, а дотик до вивіски наближає її: дошка з шістьма маленькими запитаннями, які можна позначити). На замкненому вході видно, скільки ключів залишилося. Наприкінці стежки сяйлива брама веде до йоги біля водоспаду, а звідти — до самого водоспаду.",
