    ai_chat_working_table: "Хвилинку, створюю таблицю…",
    dev_weather_preview_label: "Попередній перегляд – лише у вашому акаунті:",
    faq_a_ai_chat: "Торкніться бульбашки – відкриється чат. Оберіть, що зробити – щось у календар, що з’їдено, фото рецепта чи нову таблицю – або просто напишіть, і асистент сам зрозуміє. Можна також торкнутися 🎙️ і говорити замість того, щоб друкувати. Для календаря можна обрати один раз, щотижня або щодня. Відповідь приходить у чат, а звідти можна перейти до чогось іншого або відкрити календар / з’їдене.",
    faq_a_new_me_hall: "New Me відкривається біля брами чарівного лісу, і кожен вхід тут – це місце: круглі двері у велетенському дереві ведуть до таємної кімнати, порожниста колода – на веранду біля моря, будиночок-гриб – до гітари і щоденника, мала вербова арка – до кімнати дихання, велика вербова арка – на стежку в лісі, а квіткова арка з драбиною веде нагору, на зоряний дах, щойно він відкриється. Замкнений вхід позначено замком. Над стежкою ширяє ваш персонаж, Sky, а навколо – ігрові кнопки: наступна місія, челендж тижня, чарівний рюкзак з усім New Me, мапа світу й інструменти. Дотик до ключів угорі пояснює, як заробляти ключі.",
    faq_a_new_me_routine_meals: "Коли в New Me задано прийоми їжі, а в «Моєму розпорядку» теж є прийоми їжі, New Me запитує, чи сховати їх і показувати замість них прийоми їжі New Me – щоб нічого не з'являлося двічі. Тоді «Мій розпорядок» показує прийоми їжі New Me в їхній час, з 💎 і ✓; дотик до назви прийому їжі відкриває вікно, щоб обрати інший або змінити його час, прямо там, над розпорядком. Нічого не видаляється: вони повертаються через ⚙️ Налаштування New Me → Прийоми їжі в розпорядку або якщо вимкнути «Синхронізація з New Me» в ⚙️ «Мого розпорядку». Без активного New Me вони повертаються самі.",
    faq_a_room_computer: "Це маленький чат, що починається з питання «Як минає ваш день?» – добре, насичено чи важко – і йде з вами крок за кроком, аж до однієї маленької місії в кінці (її можна одразу додати в «Мій день»). Відповіді можна натискати або писати вільно – написане пов’язується з найближчою відповіддю. «↩ Назад» повертає на крок, щоб відповісти інакше, а «Новий чат» починає спочатку будь-коли. Після насиченого чи важкого дня можна повернутися до комп’ютера пізніше того ж дня: «Я знову тут...» продовжує розмову. Зелений вогник унизу вимикає й вмикає комп’ютер. Зберігаються лише вибори, лише на цьому пристрої й лише до кінця дня.",
    faq_q_ai_chat: "Як спілкуватися з асистентом?",
    faq_q_new_me_hall: "Що таке коридор у New Me?",
