    pcx_b2b_no: "Ні, дякую",
    pcx_b2b_q: "Втома від рішень реальна. Коли варіантів забагато, мозок просто зависає.",
    pcx_b2b_r1: "Саме так, усе ніби застрягло",
    pcx_b2b_s: "Коли ми діємо з утоми, то обираємо не той напрямок. Найрозумніший крок зараз – вивантажити все з голови.",
    pcx_b2b_t: "Візьміть аркуш або нотатку в телефоні, поставте таймер на 2 хвилини й випишіть усе, що крутиться в голові, – без порядку й без гарних формулювань.",
    pcx_b2b_tn: "Вивантаження думок",
    pcx_b2b_yes: "Так, напишу тут",
    pcx_b3_o1: "Забито від початку до кінця, ані хвилини передихнути",
    pcx_b3_o2: "Не дуже сплановано – стрибки від справи до справи за терміновістю",
    pcx_b3_q: "Відчуття, що в добі бракує годин, страшенно виснажує. Який вигляд має розклад від цього моменту до вечора?",
    pcx_b3a_ask: "О котрій буде ця перерва?",
