    pcx_br1_q: "Сюрпризи й зміни в останню мить – найнеприємніше. Здається, ніби все, що ми збудували, перемішалося. Нове завдання, що звалилося, – воно справді має статися просто зараз?",
    pcx_br1_r1: "Так, прямий тиск від керівника чи клієнта",
