    pcx_br3_s: "Це чіткий сигнал мозку: «На сьогодні я зачиняю крамничку».",
    pcx_br3_t: "Замість боротьби з утомою – завершіть день зараз: запишіть 2 перші завдання на завтрашній ранок, закрийте вкладки або комп’ютер і офіційно перемкніться у вечірній режим.",
