    pcx_c1_q: "Коли тіло втомлене чи виснажене, кожне маленьке завдання здається сходженням на гору. Де зараз проявляється ця втома?",
    pcx_c1a_q: "Ніщо так не забирає енергію й настрій, як недосип. Чи є змога трохи збавити оберти або випити щось тепле?",
