    faq_a_dictation: "Так – торкніться мікрофона 🎤 у куточку швидкої нотатки чи сторінки для письма в зошиті й говоріть: слова пишуться під час мовлення, мовою застосунку. Торкніться ще раз, щоб зупинити. Першого разу браузер попросить дозвіл на мікрофон. Працює в Chrome / Android і в Safari на iPhone. На комп'ютері потрібен мікрофон і браузер на кшталт Chrome, Edge або Safari; якщо чогось бракує, повідомлення скаже, чого саме.",
    faq_q_dictation: "Чи можна говорити замість того, щоб друкувати?",
    faq_a_secret_room: "Кімната лише для вас у New Me – дім усередині велетенського дерева. Видно одну стіну за раз, а повернутися можна стрілками (або свайпом). Перший ключ приходить після ✓ на прийомі їжі в 3 різні дні й відчиняє двері – а разом із ними всю кімнату: комп'ютер, гру, програвач, полицю з бібліотекою всередині та кота. Далі кожен завершений челендж (і челендж тижня теж) дає ключ, що відчиняє наступне місце: зоряний дах, веранду біля моря, гітару і щоденник, кімнату дихання, стежку в лісі з йогою, водоспад і сюрприз на даху – а 8-й приносить пляшку з моря з листом із минулого всередині. Коли щось відчиняється, стрілка показує шлях до нього. Маленькі дверцята внизу ігрового автомата теж відчиняються – поки що шафка за ними порожня. На зоряному даху зірка, до якої торкнулися, падає, як падуча зірка, а кіт сидить на подушці.",
