    room_wall_window_title: "Вікно й комп'ютер",
    faq_a_steps_in_sport: "Угорі розділу «Відстеження Тренувань», у маленькій смужці: кроки за сьогодні й за тиждень. Кроки рахуватимуться автоматично, коли застосунок підключиться до Google Fit / Apple Health у версії для телефона, – про це розповідає кнопка 🔗 поруч.",
    faq_q_steps_in_sport: "Де лічильник кроків за день?",
    sport_steps_today_label: "кроків сьогодні",
    sport_steps_week_label: "за тиждень",
    faq_a_reminders_one_place: "Кожне нагадування приходить один раз і в одне місце. Якщо застосунок відкрито перед вами (на комп'ютері, iPad чи телефоні), воно з'явиться там; інакше прийде сповіщенням лише на телефон. «✅ Готово, дякую!» або «Зрозуміло!» в будь-якому місці закриває його на всіх пристроях, і воно більше не повернеться. «Ще ні» відкладає його: воно повертається кожні 5 хвилин, щоразу в одне місце. Позначка ✓ біля завдання в списку теж вважається «готово». Щоб отримувати сповіщення й на комп'ютері та планшеті, увімкніть «Також на комп'ютері й планшеті» в розділі Налаштування > Сповіщення.",
    faq_q_reminders_one_place: "Чому нагадування приходить лише один раз і лише на телефон?",
    reminder_all_devices_hint: "За замовчуванням кожне нагадування приходить один раз і в одне місце: на телефон або на пристрій, де застосунок відкрито просто перед вами. «Готово» чи «Зрозуміло» в одному місці закриває його всюди.",
    reminder_all_devices_label: "Також на комп'ютері й планшеті",
    myday_water_info: "8 середніх / невеликих склянок води — це в середньому близько 2 літрів",
    faq_a_good_things: "Увечері (з 18:00) під датою з'являється маленька кнопка: запишіть до 3 гарних речей, які сталися сьогодні, — вистачить навіть однієї. Вони зберігаються, а в «Попередніх днях» видно, що ви писали раніше. «Не сьогодні» ховає її до завтра, а повністю вимкнути можна в Налаштування > Персоналізація і календар.",
    faq_a_home_countdown: "Позначте подію ⭐ у календарі (зірочка поруч із нею в списку подій). Найближча позначена подія в наступні 100 днів з'явиться під датою — «Через 3 дн. · День народження мами», «Завтра · …» або «Сьогодні · …». Торкніться її, щоб перейти до цього дня в календарі.",
    faq_a_home_streak: "Це скільки днів поспіль у вас була принаймні одна ✓ — будь-що в розділах «Мій день», «Мій розпорядок», «Мої цілі» або New Me. З'являється від 2 днів. Якщо сьогодні ✓ ще немає, серія не перервана — попереду весь день. А якщо вона закінчиться, то просто тихо зникне, без жодного почуття провини.",
    faq_a_home_weather: "Увімкніть «Погода в небі головного екрана» в Налаштування > Персоналізація і календар і дозвольте доступ до місцезнаходження. Тоді небо головного екрана показує справжню погоду там, де ви, – сонце (а вночі місяць і зорі), хмари, дощ, сніг, грозу чи туман – у кожній темі, з оновленням приблизно кожні 40 хвилин. Приблизне місцезнаходження (округлене приблизно до 1 км) лишається тільки на вашому пристрої й перевіряється через наш сервер у MET Norway. Типово вимкнено. Під перемикачем написано, яка зараз погода надворі – наприклад ⛅ Мінлива хмарність, тому на небі і сонце, і хмари.",
    faq_q_good_things: "Що таке «3 гарні речі за сьогодні»?",
    faq_q_home_countdown: "Як отримати зворотний відлік на головному екрані?",
