    settings_good_things_label: "«3 гарні речі» ввечері",
    settings_weather_hint: "Дощ, хмари чи сніг на тлі головного екрана — за погодою там, де ви. Приблизне місцезнаходження лишається на цьому пристрої й перевіряється через наш сервер у MET Norway.",
    settings_weather_label: "Погода в небі головного екрана",
    weather_failed: "Зараз не вдалося перевірити погоду.",
    weather_location_denied: "Немає доступу до місцезнаходження — дозвольте його в налаштуваннях браузера й спробуйте ще раз.",
    faq_a_home_focus: "Торкніться ◎ угорі головного екрана: зникає все, крім однієї справи на зараз – того, що на цю годину, або наступного зі списку на сьогодні – з великою ✓ і Швидкими Нотатками. Після ✓ з'являється наступна справа. Торкніться «Режим фокусу ✕» угорі, щоб усе повернулося.",
    faq_a_home_search: "Відкрийте меню ☰ — пошук у самому верху. Введіть щонайменше 2 літери: результати з нотаток, списку покупок, календаря, рецептів, зошитів (назви й текст сторінок), цілей, таблиць і книжок, згруповані за типом — торкніться результату, щоб одразу перейти до нього.",
    faq_a_my_day: "«Мій день» поєднує те, що раніше було «Поглядом на сьогодні» і «Моїм розпорядком», на одній шкалі часу. Унизу головного екрана видно, скільки вже зроблено, що зараз або далі (зі швидкою ✓), а поруч із заголовком — склянку води з +1. Торкніться (або проведіть угору), щоб відкрити весь день: угорі – те, що без часу, далі все по годинах – завдання, події та зустрічі з календаря, щотижневі сталі проміжки, сьогоднішній розпорядок, маленькі кроки ваших цілей і прийоми їжі New Me – з лінією «зараз». Фільтруйте за Завданнями, Розпорядком або Зустрічами й подіями. ✓ тут – та сама ✓, що й усюди (Мій розпорядок, Мої цілі, календар), і вона розкриває ромашку в куточку. «Змінити розпорядок» відкриває «Мій розпорядок» (він є й у меню), а «＋ Додати на сьогодні» додає завдання на сьогодні. Дотик до заголовка «Мій день» (або до смужки вгорі) знову його закриває.",
