    faq_a_goal_small_steps: "Кожна ціль у розділі «Мої цілі» – це шлях: етапи, які вже позаду, сьогоднішній камінь, що світиться, і кубок наприкінці. Задайте цілі маленький крок – на кожен день або на кожен тиждень у вибраний день – те, що вийде навіть у важкий день, наприклад «10 хвилин легкого бігу». Усі маленькі кроки на сьогодні видно вгорі розділу «Мої цілі» та в розділі «Мій день», у кожного – швидка ✓, а кнопка «✓ Сьогодні зроблено» під шляхом цілі заповнює її крапки за останні 7 днів. Записка «На шляху до 10 · не зупиняємося» навмисно завжди вгорі: не треба бути ідеальними – досить робити потроху щодня, щоб рухатися вперед.",
