    faq_a_new_me_letter_gift: "На початку New Me (або пізніше, у розділі «Челенджі») можна написати лист собі в майбутнє. Після запечатування його не можна прочитати чи змінити, доки він не відкриється: у пляшці з моря в таємній кімнаті або коли буде пройдено всі 20 челенджів – там само чекає й подарунок.",
