    faq_a_new_me_challenges: "У 🏆 Челенджах 20 челенджів: 10 великих (наприклад, 5 днів без цукру, тиждень без вуглеводів або мінус 4 кг за місяць – щодня дефіцит калорій, тренування й без цукру) і 10 міні – маленькі звички на тиждень, як-от кава з корицею без цукру. Під час вибору челенджу питається, коли почати: сьогодні, завтра, наступного тижня чи іншої дати. Великий і міні-челендж можуть тривати одночасно. Активний челендж показується вгорі меню і у розділі «Мій день», з ✓ на день. Кожен тиждень челенджу дає один вільний день (🍕), який його не перериває, а невідмічений день рахується як вільний – відмітити можна сьогодні й учора. Деякі дні відмічаються самі: 20-хвилинне тренування у «Відстеженні Тренувань» або страви з меню з ✓. Кожен челендж має ⓘ – що саме рахується (наприклад, повний список вуглеводів): у самому челенджі та поруч із ним у розділі «Мій день». Нижче, у розділі 🌱 Особистий розвиток, є 48 маленьких челенджів на один тиждень (вони не входять до цих 20) – див. «Що таке челендж тижня?».",
    faq_q_new_me_challenges: "Як працюють челенджі в New Me?",
