    nm_tile_challenges: "Челенджі",
    faq_a_workout_calories: "Так. Для кожного тренування рахується приблизна кількість спалених калорій – за типом, тривалістю та останньою вагою (для бігу та велосипеда ще й за швидкістю, якщо вказано відстань). Вона видна у списку тренувань і в місячному підсумку (Спалено) та додається до бюджету калорій цього дня: у Щоденному Трекері Їжі, у Показниках калорій і ваги та в кільці New Me. Це оцінка, тому вона зі знаком ~.",
    faq_q_workout_calories: "Чи враховуються тренування в калоріях за день?",
    faq_a_new_me_flexible_menu: "Так. В анкеті й у налаштуваннях обирають кількість прийомів їжі на день – 2 прийоми їжі + перекус / 2 прийоми їжі + легка вечеря / 2 прийоми їжі + перекус + легка вечеря, – а ➖ на картці прийому їжі прибирає його (лишаються щонайменше 3); «Повернути» повертає. У будь-якому разі калорійність дня не змінюється: прибране ділиться між іншими прийомами їжі, а під кожним видно, скільки до нього додалося і що можна додати. ✏️ Змінити відкриває текст страви – змініть що завгодно (наприклад, без хліба або з ще одним яйцем), і ШІ заново порахує калорії й білок. 🔄 Замінити пропонує варіанти з меню, ⭐ Збережені й ✨ Написати; кожна зміна може бути лише на сьогодні або відтепер. А наприкінці «Увесь день» є ➕ Додати їжу – напишіть, що було з'їдено поза меню, і ШІ порахує й додасть це до сьогодні (✕ видаляє).",
