    books_menu_label: "Куточок читання",
    faq_a_goal_tasks_peek: "Три види: щоденні завдання активного челенджу за днями (наприклад, «Без вуглеводів») – вони з'являються щодня, доки челендж не завершиться, і позначка ✓ там позначає день у цілі (і навпаки); 📅 заплановані вами етапи цілей – у призначений день, а також у календарі; і 👣 маленький крок будь-якої іншої цілі – його можна задати під час додавання або редагування цілі (на кожен день або на кожен тиждень у вибраний день). Це ті самі кроки, що й у блоці «Маленькі кроки на сьогодні» вгорі розділу «Мої цілі», у кожного – значок його цілі. +1, записане цього дня, автоматично позначає маленький крок (як і зважування, якщо маленький крок – це саме зважування).",
