    goal_share_heading: "Ціль досягнуто!",
    share_footer_sent_from: "Надіслано з NOT10.ai",
    faq_a_goal_days_challenge: "У розділі «Мої цілі» натисніть ＋ (або готовий приклад «🔥 8 днів»), виберіть «📆 Челендж за днями», вкажіть кількість днів і додайте, що потрібно робити щодня (наприклад, «Прогулянка 30 хвилин», «Харчуватися за своїм меню»). Щодня позначайте завдання цього дня під шляхом челенджу – коли позначено всі, день зараховується, шлях просувається на один камінь і росте ваша серія 🔥 (без щоденних завдань є одна кнопка «✓ Сьогодні вдалося»). Кнопка 🔁 біля завдання додає його в «Мій розпорядок» на вибрану вами годину: позначка там ставить позначку й у цілі, і навпаки. Етапи звичайної цілі можна додати в «Мій розпорядок» так само.",
    faq_q_goal_days_challenge: "Як створити челендж на кшталт «8 днів ходьби та здорового харчування» і пов'язати його з «Моїм розпорядком»?",
