    vision_focus_ribbon: "🎯 Ціль місяця",
    vision_tagline: "Великі цілі, маленькі кроки.",
    faq_a_app_tour: "Екскурсія відкривається автоматично один раз, під час першого входу. Вона починається зі своїх частин — торкніться будь-якої, щоб одразу перейти до неї, — потім показує всі частини застосунку (головний екран, помічника ШІ та кожен пункт меню) і п'ять груп налаштувань, кожну з коротким поясненням, і зазирає всередину деяких (наприклад, у зразок шляху до цілі, у сумку та в Google Calendar). «Далі» — вперед, «Назад» — назад, «Пропустити цю частину» — до наступної частини, ✕ закриває екскурсію. Переглянути її знову можна будь-коли: Налаштування > Допомога та використання > Екскурсія застосунком — і продовжити з того місця, де ви зупинилися. «Далі» і «Назад» завжди на тому самому місці внизу екрана, а на комп'ютері працюють і стрілки на клавіатурі.",
    faq_q_app_tour: "Як знову переглянути екскурсію застосунком?",
    apptour_done_text: "Є запитання? Розділ «Довідка та ЧаПи» в Налаштуваннях відповість на все, а ця екскурсія завжди доступна в розділі «Допомога та використання».",
    apptour_done_title: "От і все! 🎉",
