    apptour_m_myweek_text: "Календар на місяць, щотижневі повторювані завдання з нагадуваннями й усі події з датою. І паперовий щоденник зустрічей на тиждень 🤝.",
    apptour_m_newme_link: "Усе враховується в розділах «Щоденний Трекер Їжі» та «Мій день»; вага спільна з розділом «Показники калорій і ваги».",
    apptour_m_newme_text: "План харчування на 1300 / 1500 калорій у чарівному ігровому світі: меню на сьогодні з ✓, заміни трьома способами – з меню, зі збережених страв або написавши ШІ, що ви з'їли, і він порахує калорії – список покупок, нагадування про їжу та шлях прогресу з досягненнями, замірами й фото. А ще 🏆 20 челенджів – з подарунком наприкінці – і челендж тижня.",
