    faq_a_quick_note_apple: "🍎 поруч із 📝 і 🛒 у вікні нотаток - це ярлик для швидкого додавання однієї зі збережених страв на сьогодні в розділ «Щоденний Трекер Їжі». Типово він увімкнений - якщо він не потрібен, його можна вимкнути в Налаштування > Персоналізація і календар («Показувати ярлик 🍎 збережених страв у вікні нотаток») і будь-коли знову ввімкнути там само.",
    faq_q_quick_note_apple: "Що таке 🍎 у вікні нотаток і чи можна її приховати?",
    settings_quick_note_apple_label: "Показувати ярлик 🍎 збережених страв у вікні нотаток",
    faq_a_vision_board_today: "У розділі «Мої цілі» під шляхом цілі (у «Плані») натисніть 📅 біля етапу й виберіть дату. Можна також увімкнути «🔁 Щотижня до виконання» – тоді етап повертатиметься щотижня в той самий день, доки ви не позначите його один раз. У вибраний день етап з'явиться в розділі «Мій день» і в календарі (а також у Google Calendar, якщо його підключено), а на кнопці видно, на який день його заплановано. Позначка ✓ в одному місці ставить її й в іншому та просуває шлях цілі. Натисніть 📅 ще раз, щоб змінити дату або прибрати етап із календаря. Видалення одноразового завдання з календаря видаляє й етап із цілі; видалення одного тижня щотижневого нагадування прибирає лише цей тиждень.",
    faq_q_vision_board_today: "Як додати етап цілі до календаря (📅)?",
