    nm_drink_name_ph: "Напій (наприклад, сік)",
    nm_drinks_hint: "Достатньо ввести назву напою – калорії розраховуються автоматично, а число можна змінити.",
    nm_slot_drinks: "Напої",
    faq_a_new_me_tracking: "Торкніться наступної місії вгорі New Me, а потім ✓ З’їдено, щоб позначити, що наступний прийом їжі з’їдено, – повне меню з ✓ біля кожного прийому їжі є в «Увесь день», збоку, а сьогоднішні прийоми їжі також видно в «Моєму дні» на головному екрані – дотик до одного з них там (або наведення миші) показує, що саме з’їсти, з ✓ і «Замінити». Усе синхронізується з «Щоденним Трекером Їжі»: прийоми їжі за планом, напої та все, що додано деінде (наприклад, кава зі швидкого додавання), враховуються разом у New Me і в «Моєму дні» – нічого вже введеного не перезаписується, а зняття ✓ прибирає лише частину New Me. Коли всі сьогоднішні прийоми їжі позначено, буває маленьке свято. У «Напоях» записуються напої за день – усі разом до ~150 ккал, тобто приблизно 3 напої до ~50 ккал кожен. Досить ввести назву напою – калорії заповняться автоматично за допомогою ШІ. У двох рядках кава/чай є ще поле «Молоко? Скільки?» (наприклад, «трохи» або «50 мл»), і розрахунок оновлюється; число можна змінити і до додавання, і після. Напій із назвою й калоріями зберігається автоматично, щойно ви переходите далі, – натискати «Додати» не обов’язково. Торкніться ☆ біля напою, щоб зберегти його як звичний – звичні напої з’являються кнопками вгорі картки «Напої», і один дотик додає їх у день. ⭐ зберігає прийом їжі як збережену страву. «Щоденна таблиця» показує, що з’їдено, з калоріями й білком. Маленький 💎 поруч із режимом фокусу вгорі головного екрана відкриває його напряму. Значення калорій і білка – оцінки ШІ й можуть містити помилки. З’їдено не все? Під позначеним прийомом їжі «З’їдено не все?» віднімає чверть, половину або три чверті порції – або те, що ви напишете, з розрахунком, – і калорії дня оновлюються.",
    faq_q_new_me_tracking: "Як працюють ✓, заміни та калорії в New Me?",
    faq_a_new_me_what: "New Me – окрема програма щоденного меню з двома готовими планами – 1 300 або 1 500 калорій – з 2 основних прийомів їжі та 2 перекусів, по 3 варіанти на кожен. До неї входить увесь Преміум. Ціна: $11.99 на місяць (скасування будь-коли) або $99.99 один раз – назавжди. Відкривається через 💎 New Me у меню. Перед початком є коротка анкета, яка починається з медичного застереження, яке потрібно прийняти. Програма – це лише загальна інформація, вона не замінює лікаря чи клінічного дієтолога.",
    faq_q_new_me_what: "Що таке New Me і як його отримати?",
