    hamburger_group_planning: "Планування та Календар",
    routine_overview_no_checks: "Цього місяця ще немає позначок - торкайтеся ✓ поруч із пунктами розпорядку в дні, коли ви їх виконуєте.",
    faq_a_finance_cycle_day: "Типово підсумок вашого бюджету скидається 1-го числа кожного календарного місяця. Якщо ви отримуєте зарплату в інший день (скажімо, 10-го), вкажіть тут цей день - тоді ваш місячний підсумок, історія та цільовий бюджет відлічуватимуться від цього дня до того ж дня наступного місяця, а не з 1-го числа до кінця місяця.",
    faq_q_finance_cycle_day: "Що робить налаштування 'День скидання місячного бюджету'?",
    faq_a_quick_note_view_full_lists: "У меню ☰ одразу є «Нотатки» і «Список Покупок». У вікні швидкої нотатки (у режимі фокусу) туди ж ведуть маленькі 📝 і 🛒 біля «Додати», а 🍎 швидко записує одну з ваших збережених страв.",
