    recurring_task_tooltip: "Щотижневе повторюване завдання",
    quick_add_ai_limit_toast: "Місячну квоту ШІ вичерпано, тому використано швидшу (менш точну) оцінку. Квота оновиться наступного місяця.",
    food_estimate_local_db_reasoning: "Знайдено в нашій базі продуктів, а не вгадано ШІ. Натисніть «Це не так», якщо це не той продукт.",
    food_clarify_milk_question: "{ingredient} — це замінник молока, доданий у напій, чи окрема порція твердої їжі? Вкажіть також кількість.",
    food_ai_fallback_toast: "Зараз не вдалося отримати повну оцінку ШІ, тому це швидка приблизна оцінка. Калорії можна змінити вручну або спробувати записати ще раз трохи згодом.",
