    faq_q_daily_focus_prompt: "Що це за маленьке нагадування, яке питає, що сьогодні для мене найважливіше зробити?", faq_a_daily_focus_prompt: "Це щоденне Premium-нагадування: раз на день на значку ШІ-асистента з'являється маленький бейдж «1». Торкніться бейджа, щоб відкрити бульбашку з питанням, що для вас сьогодні найважливіше, у якій одразу видно 5 готових варіантів (вони змінюються щодня, чергуючи різні теми протягом цілого року, щоб не повторюватися) плюс 'Інше', щоб написати свій - можна вибрати кілька. Торкніться Додати, і вибране з'явиться у вигляді маленьких тегів-нагадувань угорі 'Мій день' (це не завдання для позначення). Якщо закрити її через ✕ або торкнутися поза нею, бейдж не зникає, а лише тьмяніє до кінця дня. Типово функцію ввімкнено, але її можна вимкнути в Налаштування > Персоналізація і календар. Сьогодні не той день? Натисніть «🌙 Не сьогодні» – значок зникне до завтра, а потім питання повернеться як завжди. Одна з пропозицій береться з вашого життя – наступний крок цілі місяця або сьогоднішнє читання. Кожен день починається наново.",
